using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class ApplyWarningGround11 {
 static float Surface(Vector3 p,MeshFilter[] filters){float top=0;foreach(var f in filters){var r=f.GetComponent<Renderer>();if(r==null||!r.enabled||f.sharedMesh==null||f.GetComponentInParent<Chapter45Hazard>()!=null||f.GetComponentInParent<Chapter45RoleAction>()!=null)continue;var b=r.bounds;if(p.x<b.min.x||p.x>b.max.x||p.z<b.min.z||p.z>b.max.z||b.min.y>.3f||b.max.y<0)continue;try{var v=f.sharedMesh.vertices;var tri=f.sharedMesh.triangles;for(int i=0;i<tri.Length;i+=3){var a=f.transform.TransformPoint(v[tri[i]]);var c=f.transform.TransformPoint(v[tri[i+1]]);var e=f.transform.TransformPoint(v[tri[i+2]]);float det=(c.z-e.z)*(a.x-e.x)+(e.x-c.x)*(a.z-e.z);if(Mathf.Abs(det)<.00001)continue;float u=((c.z-e.z)*(p.x-e.x)+(e.x-c.x)*(p.z-e.z))/det;float w=((e.z-a.z)*(p.x-e.x)+(a.x-e.x)*(p.z-e.z))/det;if(u<0||w<0||u+w>1)continue;float y=u*a.y+w*c.y+(1-u-w)*e.y;if(y>=0&&y<.3)top=Mathf.Max(top,y);}}catch{}}return top;}
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Clean Edit");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Preserve unsaved scenes");string original=SceneManager.GetActiveScene().path;EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");try{var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();var filters=UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None);var rows=new List<object>();foreach(var h in d.hazards){if(h.footprint==null)continue;var t=h.footprint.transform;float ground=Surface(t.position,filters);if(h.showSweepPath){ground=Mathf.Max(ground,Surface(h.body.position+h.transform.TransformDirection(h.sweepFrom),filters));ground=Mathf.Max(ground,Surface(h.body.position+h.transform.TransformDirection(h.sweepTo),filters));}float before=t.position.y;float after=Mathf.Max(before,ground+.012f);Undo.RecordObject(t,"Keep ground warning above visible road");t.position=new Vector3(t.position.x,after,t.position.z);var scale=t.localScale;t.localScale=new Vector3(scale.x,Mathf.Min(scale.y,.002f),scale.z);EditorUtility.SetDirty(t);rows.Add(new{h.name,ground,before,after,beforeThickness=scale.y,afterThickness=t.localScale.y});}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);if(!EditorSceneManager.SaveScene(d.gameObject.scene))throw new Exception("Save failed");return new{markers=rows,collidersOrBodiesChanged=false,newAssets=0};}finally{EditorSceneManager.OpenScene(original);}}
}
